import React from 'react';
import { AuthProvider } from './context/AuthContext';
import AppRouter from './routes/AppRouter';
import GlobalToasts from './components/GlobalToasts/GlobalToasts';
import './styles/global.css';

export default function App() {
  return (
    <AuthProvider>
      <AppRouter />
      <GlobalToasts />
    </AuthProvider>
  );
}

import React from 'react';
import styles from './ChatHistory.module.css';

export default function ChatHistory({ historyItems, activeId, onSelect, onNewChat }) {
  return (
    <div className={styles.historyPanel}>
      <div className={styles.header}>
        <button className={styles.newChatBtn} onClick={onNewChat}>
          <span className={styles.btnIcon}>+</span> New Chat
        </button>
        <div className={styles.searchWrap}>
          <svg className={styles.searchIcon} viewBox="0 0 24 24">
            <circle cx="11" cy="11" r="8" />
            <line x1="21" y1="21" x2="16.65" y2="16.65" />
          </svg>
          <input type="text" placeholder="Search chats..." />
        </div>
      </div>

      <div className={styles.historyList}>
        {historyItems.map((item) => (
          <div 
            key={item.id} 
            className={`${styles.historyItem} ${item.id === activeId ? styles.activeItem : ''}`}
            onClick={() => onSelect(item.id)}
          >
            <div className={styles.itemIcon}>💬</div>
            <div className={styles.itemContent}>
              <div className={styles.itemTitle}>{item.title}</div>
              <div className={styles.itemMeta}>AI Assistant</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { createManualFlashcard, updateFlashcard } from '../../services/flashcardService';
import styles from './CreateManualFlashcardModal.module.css';

export default function CreateManualFlashcardModal({ initialData, onClose, onSuccess }) {
  const [skillName, setSkillName] = useState(initialData?.skillName || '');
  const [question, setQuestion] = useState(initialData?.question || '');
  const [answer, setAnswer] = useState(initialData?.answer || '');
  const [difficulty, setDifficulty] = useState(initialData?.difficulty || '');
  const [loading, setLoading] = useState(false);

  const isEditing = !!initialData;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!question.trim() || !answer.trim()) {
      alert("Question and Answer are required!");
      return;
    }
    try {
      setLoading(true);
      const payload = {
        skillName: skillName || null,
        question,
        answer,
        difficulty: difficulty || null
      };

      if (isEditing) {
        await updateFlashcard(initialData.id, payload);
      } else {
        await createManualFlashcard(payload);
      }
      onSuccess();
    } catch (err) {
      console.error(err);
      alert('Failed to create flashcard. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.modalOverlay} onClick={onClose}>
      <div className={styles.modalContent} onClick={e => e.stopPropagation()}>

        <div className={styles.modalHeader}>
          <h2>{isEditing ? 'Edit Flashcard' : 'Create Flashcard'}</h2>
          <button className={styles.closeBtn} onClick={onClose}>×</button>
        </div>

        <form onSubmit={handleSubmit}>

          <div className={styles.formGroup}>
            <label>Skill Name (Optional)</label>
            <input 
              type="text" 
              placeholder="e.g., Python" 
              value={skillName}
              onChange={e => setSkillName(e.target.value)}
            />
          </div>

          <div className={styles.formGroup}>
            <label>Question *</label>
            <textarea 
              placeholder="Enter the front side of the flashcard..." 
              value={question}
              onChange={e => setQuestion(e.target.value)}
              required
              rows={3}
            />
          </div>

          <div className={styles.formGroup}>
            <label>Answer *</label>
            <textarea 
              placeholder="Enter the back side of the flashcard..." 
              value={answer}
              onChange={e => setAnswer(e.target.value)}
              required
              rows={4}
            />
          </div>

          <div className={styles.formGroup}>
            <label>Initial Difficulty (Optional)</label>
            <select value={difficulty} onChange={e => setDifficulty(e.target.value)}>
              <option value="">None</option>
              <option value="easy">Easy</option>
              <option value="medium">Medium</option>
              <option value="hard">Hard</option>
            </select>
          </div>

          <button 
            type="submit" 
            className={styles.submitBtn}
            disabled={loading}
          >
            {loading ? 'Saving...' : (isEditing ? 'Save Changes' : 'Create Flashcard')}
          </button>
        </form>

      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { createNote, updateNote } from '../../services/noteService';
import styles from './CreateNoteModal.module.css';

export default function CreateNoteModal({ roadmapId, dayNumber, skillName, initialData, onClose, onSuccess }) {
  const [content, setContent] = useState(initialData?.content || '');
  const [linksText, setLinksText] = useState(initialData?.resourceLinks?.join(', ') || '');
  const [skillInput, setSkillInput] = useState(initialData?.skillName || skillName || '');
  const [dayInput, setDayInput] = useState(initialData?.dayNumber || dayNumber || '');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  const isEditing = !!initialData;

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!content.trim()) {
      setError('Note content is required.');
      return;
    }

    const resourceLinks = linksText
      .split(',')
      .map(link => link.trim())
      .filter(link => link.length > 0);

    const payload = {
      roadmapId,
      dayNumber: dayInput ? parseInt(dayInput, 10) : null,
      skillName: skillInput,
      content,
      resourceLinks: resourceLinks.length > 0 ? resourceLinks : []
    };

    setSubmitting(true);
    try {
      if (isEditing) {
        await updateNote(initialData.id, payload);
      } else {
        await createNote(payload);
      }
      if (onSuccess) onSuccess();
      onClose();
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.message || err.response?.data?.error || 'Failed to save note. Ensure your links are valid and not blacklisted.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className={styles.modalBackdrop} onClick={onClose}>
      <div className={styles.modalContent} onClick={e => e.stopPropagation()}>
        <button className={styles.closeBtn} onClick={onClose}>×</button>

        <div className={styles.formContainer}>
          <div className={styles.header}>
            <div className={styles.iconBox}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"></path>
                <path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"></path>
              </svg>
            </div>
            <h2 className={styles.title}>{isEditing ? 'Edit Note' : 'Create New Note'}</h2>
          </div>

          {error && <div className={styles.errorAlert}>{error}</div>}

          <form onSubmit={handleSubmit} className={styles.form}>
            <div className={styles.formGroup}>
              <label htmlFor="note-content" className={styles.mainLabel}>Content</label>
              <textarea
                id="note-content"
                placeholder="Write your notes here..."
                value={content}
                onChange={(e) => setContent(e.target.value)}
                required
                className={styles.textareaInput}
                rows={7}
              />
            </div>

            <div className={styles.metaRow}>
              <div className={styles.metaGroup}>
                <label htmlFor="skill-input" className={styles.metaLabel}>
                  <svg className={styles.metaIcon} style={{color: '#3b82f6'}} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"></path>
                    <line x1="7" y1="7" x2="7.01" y2="7"></line>
                  </svg>
                  Skill
                </label>
                <input
                  id="skill-input"
                  type="text"
                  placeholder="e.g., React, JavaScript"
                  value={skillInput}
                  onChange={(e) => setSkillInput(e.target.value)}
                  className={styles.textInput}
                />
              </div>

              <div className={styles.metaGroup}>
                <label htmlFor="resource-links" className={styles.metaLabel}>
                  <svg className={styles.metaIcon} style={{color: '#8b5cf6'}} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path>
                    <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path>
                  </svg>
                  Links/URLs
                </label>
                <input
                  id="resource-links"
                  type="text"
                  placeholder="Reference URLs"
                  value={linksText}
                  onChange={(e) => setLinksText(e.target.value)}
                  className={styles.textInput}
                />
              </div>

              <div className={styles.metaGroup}>
                <label htmlFor="day-input" className={styles.metaLabel}>
                  <svg className={styles.metaIcon} style={{color: '#10b981'}} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
                    <line x1="16" y1="2" x2="16" y2="6"></line>
                    <line x1="8" y1="2" x2="8" y2="6"></line>
                    <line x1="3" y1="10" x2="21" y2="10"></line>
                  </svg>
                  Day
                </label>
                <input
                  id="day-input"
                  type="number"
                  placeholder="e.g., 1"
                  value={dayInput}
                  onChange={(e) => setDayInput(e.target.value)}
                  className={styles.textInput}
                />
              </div>
            </div>

            <div className={styles.actions}>
              <button type="button" className={styles.cancelBtn} onClick={onClose} disabled={submitting}>Cancel</button>
              <button type="submit" className={styles.submitBtn} disabled={submitting}>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>
                  <polyline points="17 21 17 13 7 13 7 21"></polyline>
                  <polyline points="7 3 7 8 15 8"></polyline>
                </svg>
                {submitting ? 'Saving...' : 'Save Note'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { createProject, getProjectGenerationStatus } from '../../services/projectService';
import styles from './CreateProjectModal.module.css';

const COLORS = ['blue', 'cyan', 'green', 'orange', 'red'];
const COLOR_HEX = {
  blue: '#3b82f6',
  cyan: '#06b6d4',
  green: '#10b981',
  orange: '#f59e0b',
  red: '#ef4444'
};

export default function CreateProjectModal({ onClose, onSuccess }) {
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    skillName: '',
    deadlineDays: 7,
    color: 'blue'
  });

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [jobId, setJobId] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleColorSelect = (color) => {
    setFormData(prev => ({ ...prev, color }));
  };

  const startPolling = (id) => {
    const interval = setInterval(async () => {
      try {
        const res = await getProjectGenerationStatus(id);
        const data = res.data;
        if (data) {
          setProgress(data.progress_percent || 0);
          if (data.status === 'complete') {
            clearInterval(interval);
            onSuccess(); // Close and refresh list
          } else if (data.status === 'failed') {
            clearInterval(interval);
            alert("Project generation failed: " + data.error);
            setLoading(false);
          }
        }
      } catch (err) {
        console.error("Polling error", err);
      }
    }, 2000);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name.trim()) return;

    setLoading(true);
    setProgress(10);

    try {
      const payload = {
        ...formData,
        deadlineDays: parseInt(formData.deadlineDays) || 7
      };
      const res = await createProject(payload);
      if (res.data?.job_id) {
        setJobId(res.data.job_id);
        startPolling(res.data.job_id);
      } else {
        // Fallback if no job id
        onSuccess();
      }
    } catch (err) {
      console.error(err);
      alert("Failed to create project");
      setLoading(false);
    }
  };

  return (
    <div className={styles.modalOverlay}>
      <div className={styles.modalContent}>
        <div className={styles.modalHeader}>
          <h2>New Project</h2>
          {!loading && (
            <button className={styles.closeBtn} onClick={onClose}>
              &times;
            </button>
          )}
        </div>

        {loading ? (
          <div className={styles.generatingView}>
            <div className={styles.genSpinner}>✨</div>
            <h3>Generating Project...</h3>
            <p className={styles.progressText}>AI is crafting your tasks and Kanban board</p>
            <div className={styles.progressWrapper}>
              <div 
                className={styles.progressBar} 
                style={{ width: `${progress}%` }}
              ></div>
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            <div className={styles.formGroup}>
              <label>Project Name</label>
              <input 
                type="text" 
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="e.g. Portfolio v2"
                className={styles.inputField}
                required
              />
            </div>

            <div className={styles.formGroup}>
              <label>Description</label>
              <input 
                type="text" 
                name="description"
                value={formData.description}
                onChange={handleChange}
                placeholder="Personal portfolio site rebuild"
                className={styles.inputField}
              />
            </div>

            <div className={styles.formGroup}>
              <label>Target Skill</label>
              <input 
                type="text" 
                name="skillName"
                value={formData.skillName}
                onChange={handleChange}
                placeholder="e.g. React"
                className={styles.inputField}
              />
            </div>

            <div className={styles.formGroup}>
              <label>Deadline (Days)</label>
              <input 
                type="number" 
                name="deadlineDays"
                value={formData.deadlineDays}
                onChange={handleChange}
                min="1"
                className={styles.inputField}
                required
              />
            </div>

            <div className={styles.formGroup}>
              <label>Project Color</label>
              <div className={styles.colorPicker}>
                {COLORS.map(c => (
                  <button
                    key={c}
                    type="button"
                    className={`${styles.colorOption} ${formData.color === c ? styles.selected : ''}`}
                    style={{ backgroundColor: COLOR_HEX[c] }}
                    onClick={() => handleColorSelect(c)}
                  />
                ))}
              </div>
            </div>

            <button type="submit" className={styles.btnPrimary} disabled={!formData.name.trim()}>
              Generate Project
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

import React from 'react';

export class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState({ error, errorInfo });
    console.error("ErrorBoundary caught an error", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '20px', background: '#fee2e2', color: '#991b1b', borderRadius: '8px', margin: '20px' }}>
          <h2>Something went wrong in the UI.</h2>
          <details style={{ whiteSpace: 'pre-wrap' }}>
            <summary>Click for error details</summary>
            {this.state.error && this.state.error.toString()}
            <br />
            {this.state.errorInfo && this.state.errorInfo.componentStack}
          </details>
        </div>
      );
    }
    return this.props.children; 
  }
}

import React from 'react';
import styles from './GanttChart.module.css';

export default function GanttChart({ project, entries }) {
  if (!project || !entries) return null;

  const totalDays = project.deadlineDays || 30;

  // Create array of days for the timeline header
  const daysArray = Array.from({ length: totalDays }, (_, i) => i + 1);

  const getBarClass = (color) => {
    switch(color) {
      case 'cyan': return styles.cyanBar;
      case 'green': return styles.greenBar;
      case 'orange': return styles.orangeBar;
      case 'red': return styles.redBar;
      default: return styles.blueBar;
    }
  };

  const barColorClass = getBarClass(project.color);

  // Sort entries by orderIndex
  const sortedEntries = [...entries].sort((a, b) => a.orderIndex - b.orderIndex);

  return (
    <div className={styles.ganttContainer}>
      <h2 className={styles.ganttHeader}>{project.name} &middot; Gantt Chart</h2>

      {sortedEntries.length === 0 ? (
        <div className={styles.emptyState}>No Gantt entries found for this project.</div>
      ) : (
        <div className={styles.ganttGrid}>

          {/* Y-Axis (Feature Names) */}
          <div className={styles.yAxis}>
            <div className={styles.yAxisHeader}>Features</div>
            {sortedEntries.map(entry => (
              <div key={entry.id} className={styles.yAxisRow} title={entry.featureName}>
                {entry.featureName}
              </div>
            ))}
          </div>

          {/* Timeline Grid */}
          <div className={styles.timeline}>

            {/* Header: Days */}
            <div className={styles.timelineHeader}>
              {daysArray.map(day => (
                <div key={day} className={styles.dayCell}>D{day}</div>
              ))}
            </div>

            {/* Rows with Bars */}
            {sortedEntries.map(entry => {
              // Calculate width and left offset based on percentages of total days
              const startPercent = (entry.startDay / totalDays) * 100;
              const widthPercent = (entry.durationDays / totalDays) * 100;

              return (
                <div key={entry.id} className={styles.timelineRow}>
                  {/* Background Grid Lines */}
                  {daysArray.map(day => (
                    <div key={day} className={styles.gridLine}></div>
                  ))}

                  {/* Actual Gantt Bar */}
                  <div 
                    className={`${styles.ganttBar} ${barColorClass}`}
                    style={{
                      left: `${Math.max(0, startPercent)}%`,
                      width: `${Math.min(100 - startPercent, widthPercent)}%`
                    }}
                    title={`${entry.featureName} (Days ${entry.startDay + 1}-${entry.startDay + entry.durationDays})`}
                  >
                    {entry.durationDays}d
                  </div>
                </div>
              );
            })}
          </div>

        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { generateRoadmap, getRoadmapGenerationStatus } from '../../services/roadmapService';
import styles from './GenerateRoadmapModal.module.css';

export default function GenerateRoadmapModal({ onClose, onSuccess }) {
  const navigate = useNavigate();

  // Form Fields
  const [skillGoal, setSkillGoal] = useState('');
  const [dailyTimeMinutes, setDailyTimeMinutes] = useState(60);
  const [durationMonths, setDurationMonths] = useState(3);
  const [goalPurpose, setGoalPurpose] = useState('job');
  const [level, setLevel] = useState('beginner');
  const [experienceDescription, setExperienceDescription] = useState('');
  const [focusAreasText, setFocusAreasText] = useState('');

  // UI State
  const [generating, setGenerating] = useState(false);
  const [status, setStatus] = useState('');
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState('');

  const handleStartGeneration = async (e) => {
    e.preventDefault();
    setError('');

    if (!skillGoal.trim()) {
      setError('Please enter a learning goal (e.g. React Frontend Developer).');
      return;
    }

    const focusAreas = focusAreasText
      .split(',')
      .map(tag => tag.trim())
      .filter(tag => tag.length > 0);

    const payload = {
      skillGoal,
      dailyTimeMinutes,
      durationMonths,
      goalPurpose,
      level,
      experienceDescription: experienceDescription || null,
      focusAreas: focusAreas.length > 0 ? focusAreas : null
    };

    setGenerating(true);
    setProgress(5);
    setStatus('Initializing AI Generator...');

    try {
      const res = await generateRoadmap(payload);
      const { job_id } = res.data;
      setStatus('Prompt sent to Gemini AI...');
      setProgress(15);

      startPolling(job_id);
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.message || err.response?.data?.error || 'Failed to submit roadmap request. Please try again.');
      setGenerating(false);
    }
  };

  const startPolling = (id) => {
    let attempts = 0;
    const interval = setInterval(async () => {
      attempts++;
      if (attempts > 150) {
        clearInterval(interval);
        setError('Roadmap generation timed out. Please try again later.');
        setGenerating(false);
        return;
      }

      try {
        const statusRes = await getRoadmapGenerationStatus(id);
        const { status: jobStatus, progress_percent, result_id, error: jobError } = statusRes.data;

        setProgress(progress_percent || 20);

        if (jobStatus === 'processing') {
          setStatus('AI is constructing curriculum chapters and daily lessons...');
        } else if (jobStatus === 'complete') {
          setStatus('Roadmap created successfully! Loading timeline...');
          clearInterval(interval);
          setTimeout(() => {
            if (onSuccess) onSuccess(result_id);
            else onClose();
          }, 1000);
        } else if (jobStatus === 'failed') {
          setError(jobError || 'Gemini AI failed to structure the roadmap. Please try again.');
          clearInterval(interval);
          setGenerating(false);
        }
      } catch (err) {
        console.error('Polling error:', err);
        if (attempts > 10) {
          clearInterval(interval);
          setError('Lost connection to backend server. Roadmap generation may still be running.');
          setGenerating(false);
        }
      }
    }, 2500);
  };

  return (
    <div className={styles.modalBackdrop} onClick={onClose}>
      <div className={styles.modalContent} onClick={e => e.stopPropagation()}>
        <button className={styles.closeBtn} onClick={onClose}>×</button>

        {!generating ? (
          <div className={styles.formContainer}>
            <div className={styles.header}>
              <div className={styles.iconBox}>🤖</div>
              <div>
                <h2 className={styles.title}>Generate New Roadmap</h2>
                <p className={styles.subtitle}>Provide your goals, and let AI build a custom daily study plan.</p>
              </div>
            </div>

            {error && <div className={styles.errorAlert}>{error}</div>}

            <form onSubmit={handleStartGeneration} className={styles.form}>

              <div className={styles.formGroup}>
                <div className={styles.labelRow}>
                  <label htmlFor="skill-goal">Target Skill / Goal <span className={styles.required}>*</span></label>
                  <div className={styles.tooltipWrapper}>
                    <span className={styles.infoIcon}>i</span>
                    <div className={styles.tooltipContent}>This defines the core theme of your roadmap. Be as specific as you like.</div>
                  </div>
                </div>
                <input 
                  id="skill-goal"
                  type="text" 
                  placeholder="e.g. Fullstack Web Developer, Machine Learning" 
                  value={skillGoal}
                  onChange={(e) => setSkillGoal(e.target.value)}
                  required
                  className={styles.textInput}
                />
              </div>

              <div className={styles.grid2}>
                <div className={styles.formGroup}>
                  <div className={styles.labelRow}>
                    <label htmlFor="level">Experience Level <span className={styles.required}>*</span></label>
                    <div className={styles.tooltipWrapper}>
                      <span className={styles.infoIcon}>i</span>
                      <div className={styles.tooltipContent}>"Beginner" starts from absolute basics, while "Advanced" skips fundamentals.</div>
                    </div>
                  </div>
