import React, { useEffect, useRef } from 'react';
import styles from './NotificationsDropdown.module.css';

export default function NotificationsDropdown({ notifications, onClose, onMarkAllRead }) {
  const dropdownRef = useRef(null);

  // Close when clicking outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        onClose();
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [onClose]);

  const getIconForType = (type) => {
    switch (type) {
      case 'ACHIEVEMENT_UNLOCKED':
      case 'PEER_ACHIEVEMENT':
        return '🏆';
      case 'LEVEL_UP':
        return '🌟';
      case 'PEER_REQUEST_ACCEPTED':
      case 'PEER_REQUEST_RECEIVED':
        return '👥';
      case 'PEER_MESSAGE':
        return '💬';
      case 'PEER_STREAK_BROKEN':
        return '💔';
      case 'PEER_TASK_MISSED':
        return '⏰';
      default:
        return '🔔';
    }
  };

  const getIconClass = (type) => {
    if (type.includes('ACHIEVEMENT')) return styles.iconYellow;
    if (type.includes('PEER')) return styles.iconBlue;
    if (type.includes('LEVEL')) return styles.iconGreen;
    return styles.iconGray;
  };

  const formatTimeAgo = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const seconds = Math.floor((now - date) / 1000);

    if (seconds < 60) return `${seconds}s ago`;
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m ago`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    return `${days}d ago`;
  };

  return (
    <div className={styles.dropdownOverlay}>
      <div className={styles.dropdownContainer} ref={dropdownRef}>
        <div className={styles.header}>
          <h3>Notifications</h3>
          <button className={styles.markReadBtn} onClick={onMarkAllRead}>
            Mark all read
          </button>
        </div>

        <div className={styles.list}>
          {notifications.length === 0 ? (
            <div className={styles.emptyState}>No new notifications</div>
          ) : (
            notifications.map((notif) => (
              <div 
                key={notif.id} 
                className={`${styles.notificationItem} ${!notif.isRead ? styles.unread : ''}`}
              >
                <div className={`${styles.iconWrapper} ${getIconClass(notif.type)}`}>
                  {getIconForType(notif.type)}
                </div>
                <div className={styles.content}>
                  <div className={styles.titleRow}>
                    <p className={styles.title}>{notif.title}</p>
                    {!notif.isRead && <span className={styles.unreadDot}></span>}
                  </div>
                  <p className={styles.body}>{notif.body}</p>
                  <span className={styles.time}>{formatTimeAgo(notif.createdAt)}</span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { updateRoadmap, deleteRoadmap } from '../../services/roadmapService';
import styles from './SwitchRoadmapModal.module.css';

export default function SwitchRoadmapModal({ roadmaps, onClose, onUpdate }) {
  const [loadingId, setLoadingId] = useState(null);

  const handleSetActive = async (id) => {
    try {
      setLoadingId(id);
      await updateRoadmap(id, { status: 'active' });
      onUpdate(); // Triggers parent to fetch roadmaps again
      onClose();  // Close modal so page refreshes immediately
    } catch (err) {
      console.error(err);
      alert('Failed to set active roadmap');
      setLoadingId(null);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this roadmap? This action cannot be undone.')) {
      return;
    }

    try {
      setLoadingId(id);
      await deleteRoadmap(id);
      onUpdate(); // Refresh the list
    } catch (err) {
      console.error(err);
      alert('Failed to delete roadmap');
      setLoadingId(null);
    }
  };

  return (
    <div className={styles.modalBackdrop} onClick={onClose}>
      <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
        <div className={styles.modalHeader}>
          <h3>Switch Roadmap</h3>
          <button className={styles.closeBtn} onClick={onClose}>×</button>
        </div>

        <div className={styles.modalBody}>
          {roadmaps.length === 0 ? (
            <p className={styles.emptyText}>You haven't generated any roadmaps yet.</p>
          ) : (
            <div className={styles.list}>
              {roadmaps.map((rm) => {
                const isActive = rm.status === 'active';
                return (
                  <div key={rm.id} className={`${styles.roadmapItem} ${isActive ? styles.activeItem : ''}`}>

                    <div className={styles.itemInfo}>
                      <div className={styles.itemHeader}>
                        <h4>{rm.title}</h4>
                      </div>
                      <p className={styles.itemMeta}>🎯 {rm.skillGoal} • 📅 {rm.durationMonths} Months</p>
                    </div>

                    <div className={styles.itemActions}>
                      <button
                        className={isActive ? styles.activeToggle : styles.activateBtn}
                        onClick={() => !isActive && handleSetActive(rm.id)}
                        disabled={loadingId === rm.id || isActive}
                        title={isActive ? 'Currently active' : 'Set as active roadmap'}
                      >
                        {loadingId === rm.id ? '...' : isActive ? 'Active ✓' : 'Set Active'}
                      </button>

                      <button 
                        className={styles.deleteBtn}
                        onClick={() => handleDelete(rm.id)}
                        title="Delete Roadmap"
                        disabled={loadingId === rm.id}
                      >
                        <svg viewBox="0 0 24 24" width="18" height="18" stroke="currentColor" fill="none" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <polyline points="3 6 5 6 21 6"></polyline>
