    <div className={styles.layoutContainer}>
      <Sidebar collapsed={sidebarCollapsed} onToggle={handleToggleSidebar} />

      <div className={`${styles.mainContent} ${sidebarCollapsed ? styles.collapsed : ''}`}>
        <Topbar onToggleSidebar={handleToggleSidebar} />
        <main className={styles.contentBody}>
          {children}
        </main>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import { loginUser, registerUser } from '../../services/authService';
import styles from './AuthPage.module.css';

export default function AuthPage() {
  const [isLogin, setIsLogin] = useState(true);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const { login } = useAuth();
  const navigate = useNavigate();

  const handleToggleMode = () => {
    setIsLogin(!isLogin);
    setError('');
    setFullName('');
    setEmail('');
    setPassword('');
    setConfirmPassword('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!email || !password) {
      setError('Please fill in all required fields.');
      setLoading(false);
      return;
    }

    if (!isLogin) {
      if (!fullName) {
        setError('Please enter your full name.');
        setLoading(false);
        return;
      }
      if (password !== confirmPassword) {
        setError('Passwords do not match.');
        setLoading(false);
        return;
      }
    }

    try {
      if (isLogin) {
        const response = await loginUser({ email, password });
        const { accessToken, user } = response.data;
        login(accessToken, user);
        navigate('/dashboard');
      } else {
        const response = await registerUser({ fullName, email, password });
        const { accessToken, user } = response.data;
        login(accessToken, user);
        navigate('/dashboard');
      }
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error?.message || err.response?.data?.message || (typeof err.response?.data?.error === 'string' ? err.response?.data?.error : 'Authentication failed. Please try again.'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      {/* Left Branding Section */}
      <div className={styles.leftSide}>
        <div className={styles.brand}>
          <div className={styles.logoMark}>S</div>
          <span className={styles.logoText}>SkillOS</span>
        </div>

        <div className={styles.heroText}>
          <h1 className={styles.heroTitle}>
            {isLogin ? (
              <>Welcome back,<br />learner.</>
            ) : (
              <>Join 12,000+<br />learners today.</>
            )}
          </h1>
          <p className={styles.heroDesc}>
            {isLogin 
              ? "Pick up where you left off and keep your streak alive."
              : "Build skills, track progress, and stay accountable — every day."
            }
          </p>
        </div>

        {isLogin ? (
          <div className={styles.heroStats}>
            <div className={styles.statItem}>
              <h3>12k+</h3>
              <p>Active Learners</p>
            </div>
            <div className={styles.statItem}>
              <h3>94%</h3>
              <p>Completion Rate</p>
            </div>
            <div className={styles.statItem}>
              <h3>4.9</h3>
              <p>Store Rating</p>
            </div>
          </div>
        ) : (
          <div className={styles.heroSpacer}></div>
        )}
      </div>

      {/* Right Form Section */}
      <div className={styles.rightSide}>
        <div className={styles.authCard}>
          {error && <div className={styles.errorAlert}>{error}</div>}

          {isLogin ? (
            /* Login Form */
            <div className={styles.loginFormBlock}>
              <h2>Welcome Back</h2>
              <p className={styles.cardSubtitle}>Enter your details to access your dashboard</p>

              <form onSubmit={handleSubmit}>
                <div className={styles.formGroup}>
                  <label htmlFor="login-email">Email Address</label>
                  <input 
                    id="login-email"
                    type="email" 
                    placeholder="you@example.com" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                  />
                </div>

                <div className={styles.formGroup}>
                  <div className={styles.labelRow}>
                    <label htmlFor="login-password">Password</label>
                    <a href="#forgot" className={styles.forgotLink}>Forgot?</a>
                  </div>
                  <div className={styles.passwordInputWrap}>
                    <input 
                      id="login-password"
                      type={showPassword ? "text" : "password"} 
                      placeholder="••••••••" 
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      required
                    />
                    <span 
                      className={styles.eyeToggle} 
                      onClick={() => setShowPassword(!showPassword)}
                      style={{ color: showPassword ? '#4338CA' : '#6B7280' }}
                    >
                      👁
                    </span>
                  </div>
                </div>

                <button type="submit" className={styles.submitBtn} disabled={loading}>
                  {loading ? 'Logging in...' : 'Log In'}
                </button>
              </form>

              <div className={styles.divider}>
                <span>or continue with</span>
              </div>

              <div className={styles.socialBtns}>
                <button className={styles.socialBtn}>
                  <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="Google" />
                  Google
                </button>
                <button className={styles.socialBtn}>
                  <img src="https://www.svgrepo.com/show/512317/github-142.svg" alt="GitHub" />
                  GitHub
                </button>
              </div>

              <p className={styles.switchText}>
                Don't have an account? <span onClick={handleToggleMode} className={styles.switchLink}>Sign up</span>
              </p>
            </div>
          ) : (
            /* Signup Form */
            <div className={styles.signupFormBlock}>
              <h2>Create Account</h2>
              <p className={styles.cardSubtitle}>Join the community and start leveling up today</p>

              <form onSubmit={handleSubmit}>
                <div className={styles.formGroup}>
                  <label htmlFor="signup-name">Full Name</label>
                  <input 
                    id="signup-name"
                    type="text" 
                    placeholder="John Doe" 
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    required
                  />
                </div>

                <div className={styles.formGroup}>
                  <label htmlFor="signup-email">Email Address</label>
                  <input 
                    id="signup-email"
                    type="email" 
                    placeholder="you@example.com" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                  />
                </div>

                <div className={styles.formGroup}>
                  <label htmlFor="signup-password">Password</label>
                  <div className={styles.passwordInputWrap}>
                    <input 
                      id="signup-password"
                      type={showPassword ? "text" : "password"} 
                      placeholder="At least 8 characters" 
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      required
                    />
                    <span 
                      className={styles.eyeToggle} 
                      onClick={() => setShowPassword(!showPassword)}
                      style={{ color: showPassword ? '#4338CA' : '#6B7280' }}
                    >
                      👁
                    </span>
                  </div>
                </div>

                <div className={styles.formGroup}>
                  <label htmlFor="signup-confirm">Confirm Password</label>
                  <input 
                    id="signup-confirm"
                    type="password" 
                    placeholder="••••••••" 
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    required
                  />
                </div>

                <button type="submit" className={styles.submitBtn} disabled={loading}>
                  {loading ? 'Creating Account...' : 'Sign Up'}
                </button>
              </form>

              <div className={styles.divider}>
                <span>or signup with</span>
              </div>

              <div className={styles.socialBtns}>
                <button className={styles.socialBtn}>
                  <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="Google" />
                  Google
                </button>
                <button className={styles.socialBtn}>
                  <img src="https://www.svgrepo.com/show/512317/github-142.svg" alt="GitHub" />
                  GitHub
                </button>
              </div>

              <p className={styles.switchText}>
                Already have an account? <span onClick={handleToggleMode} className={styles.switchLink}>Log in</span>
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import DashboardLayout from '../../layouts/DashboardLayout';
import GenerateRoadmapModal from '../../components/GenerateRoadmapModal/GenerateRoadmapModal';
import CreateNoteModal from '../../components/CreateNoteModal/CreateNoteModal';
import { getDashboard } from '../../services/dashboardService';
import { getPlannerDashboard } from '../../services/plannerService';
import { useAuth } from '../../hooks/useAuth';
import styles from './DashboardPage.module.css';

export default function DashboardPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [data, setData] = useState(null);
  const [plannerData, setPlannerData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isGenerateModalOpen, setIsGenerateModalOpen] = useState(false);
  const [isNoteModalOpen, setIsNoteModalOpen] = useState(false);

  useEffect(() => {
    Promise.all([
      getDashboard(),
      getPlannerDashboard()
    ])
      .then(([dashboardRes, plannerRes]) => {
        setData(dashboardRes.data);
        setPlannerData(plannerRes);
      })
      .catch((err) => {
        console.warn('Dashboard fetch failed', err);
      })
      .finally(() => {
        setLoading(false);
      });
  }, [user]);

  if (loading || !data) {
    return (
      <DashboardLayout>
        <div className={styles.loadingContainer}>Loading Dashboard...</div>
      </DashboardLayout>
    );
  }

  const {
    greeting,
    targetGoal,
    activeRoadmap,
  } = data;

  const getUpcomingTasks = () => {
    if (!plannerData?.today?.entries) return [];
    const now = new Date();
    const currentMinutes = now.getHours() * 60 + now.getMinutes();

    return plannerData.today.entries.filter(entry => {
      if (entry.status === 'completed') return false;
      const [eh, em] = entry.endTime.split(':');
      const endMinutes = parseInt(eh) * 60 + parseInt(em);
      return endMinutes > currentMinutes; // Upcoming or currently active
    }).slice(0, 4);
  };
  const upcomingPlannerTasks = getUpcomingTasks();

  const formatTime = (timeStr) => {
    if (!timeStr) return '';
    const [h, m] = timeStr.split(':');
    const d = new Date();
    d.setHours(parseInt(h, 10));
    d.setMinutes(parseInt(m, 10));
    return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  };

  return (
    <DashboardLayout>
      <div className={styles.dashboardContainer}>
        {/* ── HERO BANNER ── */}
        <div className={styles.heroBanner}>
          <div className={styles.heroHeader}>
            <h1 className={styles.greetingText}>{greeting || `Welcome back, ${user?.fullName}!`}</h1>
            <p className={styles.bannerSubtitle}>
              You're working toward: {targetGoal || 'Mastering your skills'}
            </p>
          </div>
        </div>

        {/* ── MIDDLE CARDS ROW ── */}
        <div className={styles.middleCardsRow}>
          {/* Active Roadmap */}
          <div className={styles.cardBox}>
            <div className={styles.cardHeader}>
              <span className={styles.cardIcon}>✨</span>
              <span>ACTIVE ROADMAP</span>
            </div>
            <h3 className={styles.cardTitle}>{activeRoadmap?.title || 'No Roadmap'}</h3>
            <p className={styles.roadmapSubtitle}>{activeRoadmap?.subtitle || '0% complete'}</p>
            <div className={styles.progressContainer}>
              <div 
                className={styles.progressFill} 
                style={{ width: `${activeRoadmap?.percent || 0}%` }}
              ></div>
            </div>
            <div className={styles.continueLink} onClick={() => navigate('/roadmaps')}>
              Continue {'>'}
            </div>
          </div>
        </div>

        {/* ── BOTTOM GRID ── */}
        <div className={styles.bottomGrid}>
          {/* Quick Actions */}
          <div className={styles.sectionBox}>
            <h3 className={styles.sectionTitle}>Quick Actions</h3>
            <div className={styles.quickActionsGrid}>
              <div className={styles.actionCard} onClick={() => setIsNoteModalOpen(true)}>
                <div className={styles.actionCardIcon} style={{ color: '#f59e0b' }}>📄</div>
                <div className={styles.actionCardText}>Add Note</div>
              </div>
              <div className={styles.actionCard} onClick={() => navigate('/roadmaps')}>
                <div className={styles.actionCardIcon} style={{ color: '#10b981' }}>🧠</div>
                <div className={styles.actionCardText}>Study Roadmaps</div>
              </div>
            </div>
          </div>

          {/* Upcoming Planner Tasks */}
          <div className={styles.sectionBox}>
            <h3 className={styles.sectionTitle}>Upcoming in Planner</h3>
            {upcomingPlannerTasks.length === 0 ? (
              <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem', marginTop: '10px' }}>
                No upcoming tasks today.
              </p>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginTop: '12px' }}>
                {upcomingPlannerTasks.map(task => {
                  const isExternal = task.sourceType === 'external' || task.sourceType === 'google_calendar';
                  return (
                    <div key={task.id} className={styles.upcomingTaskItem} onClick={() => navigate('/planner')}>
                      <div className={styles.upcomingTaskTime}>
                        {formatTime(task.startTime)}
                      </div>
                      <div className={styles.upcomingTaskInfo}>
                        <div className={styles.upcomingTaskTitle}>{task.taskTitle || task.title}</div>
                        <div className={`${styles.upcomingTaskBadge} ${isExternal ? styles.badgeExternal : styles.badgeCustom}`}>
                          {isExternal ? 'Calendar' : 'SkillOS'}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </div>

      {isGenerateModalOpen && (
        <GenerateRoadmapModal 
          onClose={() => setIsGenerateModalOpen(false)}
          onSuccess={() => {
            setIsGenerateModalOpen(false);
            navigate('/roadmaps');
          }}
        />
      )}

      {isNoteModalOpen && (
        <CreateNoteModal 
          onClose={() => setIsNoteModalOpen(false)}
          onSuccess={() => {
            setIsNoteModalOpen(false);
          }}
        />
      )}
    </DashboardLayout>
  );
}

